  public static function initLogger(): void
  {
    static $loggerSet = false;

    if ($loggerSet) {
      return;
    }

    // Register a custom log file for com_topiau
    \Joomla\CMS\Log\Log::addLogger(
      [
        'text_file' => 'topiau.php', // File: administrator/logs/.php
        'extension' => 'com_topiau',          // Prefix inside the log file
        'text_entry_format' => '{DATETIME} {PRIORITY} {CATEGORY} {MESSAGE}'
      ],
      \Joomla\CMS\Log\Log::ALL,                // log all levels: DEBUG, INFO, WARNING, ERROR
      ['com_topiau']          // Only log entries with this category
    );

    $loggerSet = true;
  }

  /**
     * Example wrapper for error logging.
     */

  public static function logError(string $message, array $context = []): void
  {
    self::initLogger();

    $fullMessage = $message;

    if (!empty($context)) {
      $fullMessage .= ' | Context: ' . json_encode($context, JSON_UNESCAPED_SLASHES);
    }

    \Joomla\CMS\Log\Log::add($fullMessage, \Joomla\CMS\Log\Log::ERROR, 'com_topiau');
  }
 public static function logTrace(string $message, array $context = []): void
  {
    self::initLogger();

    $fullMessage = $message;

    if (!empty($context)) {
      $fullMessage .= ' | Context: ' . json_encode($context, JSON_UNESCAPED_SLASHES);
    }

    \Joomla\CMS\Log\Log::add($fullMessage, \Joomla\CMS\Log\Log::NOTICE, 'com_topiau');
  }

public static function getMyQuestions($user){
    self::logTrace('getMyQuestions', ['user ' => $user]);
  
    $db = Factory::getContainer()->get(DatabaseInterface::class);
    $query = $db->getQuery(true);
    $query
      ->select('*')
      ->from($db->quoteName('#__topiau_question'))
      ->where($db->quoteName('created_by') . ' = '.$db->quote($user->id) )
   
      ;
    $db->setQuery($query);   
    $result = $db->loadObjectList();
   self::logTrace('getMyQuestions', ['SQL' => $query->__toString()]);
   self::logTrace('getMyQuestions', ['Result ' => $result]);
    return $result;

  }
